// Шейдер BLUR_HLSL (effects.pas). Строки-комментарии // в exe не попадают: build.ps1 собирает
// файл в константу (build\gen\blur_hlsl.inc).
sampler2D spr : register(s0);
float4 texel : register(c0);
float4 prm : register(c1);
float4 main(float2 uv : TEXCOORD0, float4 col : COLOR0) : COLOR0
{
  float2 r = texel.xy * prm.x;
  float2 h = r * 0.5;
  float4 s = tex2D(spr, uv) * 0.16;
  s += (tex2D(spr, uv + float2(h.x, 0)) + tex2D(spr, uv - float2(h.x, 0)) +
        tex2D(spr, uv + float2(0, h.y)) + tex2D(spr, uv - float2(0, h.y))) * 0.11;
  s += (tex2D(spr, uv + r * float2(0.71, 0.71)) + tex2D(spr, uv + r * float2(-0.71, 0.71)) +
        tex2D(spr, uv + r * float2(0.71, -0.71)) + tex2D(spr, uv + r * float2(-0.71, -0.71)) +
        tex2D(spr, uv + float2(r.x, 0)) + tex2D(spr, uv - float2(r.x, 0)) +
        tex2D(spr, uv + float2(0, r.y)) + tex2D(spr, uv - float2(0, r.y))) * 0.05;
  return s * col;
}

