shaders.hlsl:
// Шейдер WATER_HLSL (water.pas). Строки-комментарии // в exe не попадают: build.ps1 собирает
// файл в константу (build\gen\water_hlsl.inc).
sampler2D scn : register(s0);
sampler2D grd : register(s1);
sampler2D srf : register(s2);
sampler2D cst : register(s3);
float4 k0 : register(c0);
float4 rc : register(c1);
float4 sw : register(c2);
float4 pr : register(c3);
float4 tn : register(c4);
float4 sf : register(c5);
float4 gm : register(c6);
float4 mr : register(c7);
float4 cv[21] : register(c8);
float4 ct : register(c29);
float4 hz : register(c30);
float4 dz : register(c31);
float4 sw1 : register(c32);
float4 sw2 : register(c33);
float4 sw3 : register(c34);
float4 fr : register(c35);
float4 cz : register(c36);
float4 ctr : register(c37);
float4 cts : register(c38);
float4 st : register(c39);
// Волна зыби: смещение, наклон и кривизна синуса (x — волновое число, y — частота, z — размах, w — фаза)
float3 swell(float x, float t, float4 q)
{
  float a = x * q.x + t * q.y + q.w;
  return float3(sin(a), q.x * cos(a), -q.x * q.x * sin(a)) * q.z;
}
// Кромка над точкой x: смещение вниз от покоя (h), наклон (s.x) и кривизна (s.y) — зыбь (три волны,
// TWater.SwellAt) плюс живая поверхность из текстуры (r — смещение, g — наклон, b — кривизна; как
// TWater.UploadSurface)
float3 surface(float x, float t)
{
  float3 z = swell(x, t, sw1) + swell(x, t, sw2) + swell(x, t, sw3);
  float u = ((x - sf.x) * sf.y + 0.5) * sf.z;
  float3 f = tex2D(srf, float2(u, 0.5)).rgb * 255 - 128;
  return float3(z.x + f.r * 0.5, z.y + f.g / 127, z.z + f.b / 2540);
}
  // Каустика: нули суммы трёх «скрученных» синусов — тонкая сетка светлых линий, медленно текущая
float caustic(float2 p, float t)
{
  float2 q = p * 0.011;
  float v = sin(q.x * 3.1 + t * 0.9 + sin(q.y * 2.3 + t * 0.7) * 1.6) +
    sin(q.y * 3.7 - t * 0.8 + sin(q.x * 2.9 - t * 0.6) * 1.6) + sin((q.x + q.y) * 2.6 + t * 1.1);
  float a = saturate(1 - abs(v) * 0.9);
  return a * a * a * a;
}
// Каустика плиткой художника (mr.w = 1): плитка ct (u0, v0, du, dv в атласе s3), мировой размер — dz.w; два слоя
// одной плитки разного размера едут навстречу, светлое — где оба светлые (сетка всё время перестраивается);
// ниже mr.z — тёмная заливка плитки, не свет
float causticTile(float2 p, float t)
{
  float2 q1 = p / dz.w + float2(t * 0.021, t * 0.013);
  float2 q2 = p / (dz.w * 1.37) + float2(0.37 - t * 0.017, 0.11 + t * 0.019);
  float a = tex2D(cst, ct.xy + frac(q1) * ct.zw).g;
  float b = tex2D(cst, ct.xy + frac(q2) * ct.zw).g;
  return saturate((min(a, b) - mr.z) / (1 - mr.z));
}
float4 main(float2 uv : TEXCOORD0, float4 col : COLOR0) : COLOR0
{
  float2 w = rc.xy + uv * rc.zw;
  float t = sw.w;
  float3 sh = surface(w.x, t);
  float h = sh.x;
  float dy = w.y - sw.x;
  // Кромка нарисована на фоне — картинка у кромки сдвигается на высоту волны, к краям полосы — плавно меньше
  float bump = saturate(1 - abs(dy) / (dy < 0 ? pr.x : pr.y));
  bump = bump * bump * (3 - 2 * bump);
  float d = dy - h;
  float under = saturate(d / 30);
  // Воздух и ил в воде (сетка течения): r — мелкие пузырьки, g — муть; пузырчатая вода преломляет неровно;
  // b — взбаламученность (со знаком, ноль — 128)
  float2 gq = (w - gm.xy) * gm.zw;
  float3 gs = tex2D(grd, gq).rgb;
  float2 ga = gs.rg;
  float axl = tex2D(grd, gq - float2(gm.z * 10, 0)).r;
  float ayu = tex2D(grd, gq - float2(0, gm.w * 10)).r;
  // Искажение по глубине (dz.z = 1): у кромки к крупной волне добавляется мелкая быстрая рябь и сдвиг сильнее,
  // глубже остаются только крупные медленные волны, слабее
  float nz = exp(-max(d, 0) / dz.y) * dz.z;
  float ka = lerp(1, 0.35 + 1.3 * nz, dz.z);
  float2 off;
  // Мелкая рябь у кромки — масштаб fr.x (меньше — крупнее) и скорость fr.y
  float2 fw = w * fr.x;
  float ft = t * fr.y;
  off.x = (sin(w.y * 0.05 + t * 1.3 + sin(w.x * 0.012 + t * 0.5) * 2) * ka +
    sin(fw.y * 0.13 + ft * 3.1 + sin(fw.x * 0.037 - ft * 1.4) * 1.5) * 0.7 * nz) * pr.z * under;
  off.y = -h * bump + (cos(w.x * 0.04 - t * 1.1) * 0.5 * ka + cos(fw.x * 0.11 + ft * 2.6) * 0.4 * nz) * pr.z * under;
  off += float2(ga.r - axl, ga.r - ayu) * 5 * under;
  // Взбаламученная вода: мелкие вихри за ластами преломляют неровно — картинка за ней ходит линзами (перепад поля
  // через клетку, cz.x px). Линзы плывут с водой, гребки туда и обратно — разного знака: за ластами бежит волна
  float2 cg = float2(tex2D(grd, gq + float2(cz.z, 0)).b - tex2D(grd, gq - float2(cz.z, 0)).b,
    tex2D(grd, gq + float2(0, cz.w)).b - tex2D(grd, gq - float2(0, cz.w)).b) * (255.0 / 254);
  off += cg * cz.x * under;
  // И завитками (cts.z > 0): плитка художника ctr — рельеф вихрей, cts.xy — её размер в мире; картинка сдвигается по
  // её наклону, сильнее — где вода взбаламучена сильнее. Выборка плитки едет вместе с полем: пятно проплывает —
  // завитки под ним катятся, а не стоят на месте
  if (cts.z > 0)
  {
    float ch = (gs.b * 255 - 128) / 127;
    float2 q = w / cts.xy + float2(t * 0.013, -t * 0.009) + ch * float2(0.12, 0.07);
    float2 e = float2(cts.w, cts.w * cts.x / cts.y);
    float2 hs = float2(tex2D(cst, ctr.xy + frac(q + float2(e.x, 0)) * ctr.zw).g -
      tex2D(cst, ctr.xy + frac(q - float2(e.x, 0)) * ctr.zw).g,
      tex2D(cst, ctr.xy + frac(q + float2(0, e.y)) * ctr.zw).g - tex2D(cst, ctr.xy + frac(q - float2(0, e.y)) * ctr.zw).g);
    off += hs * 16 * cts.z * abs(ch) * under;
  }
  float2 suv = clamp(uv + off / rc.zw, k0.xy, 1 - k0.xy);
  float3 c = tex2D(scn, suv).rgb;
  // Изнанка поверхности (полное внутреннее отражение): полоса под кромкой зеркалит толщу под собой; волна
  // качает отражение
  float m = saturate(d / mr.x);
  float mw = (1 - m) * (1 - m) * saturate(d / 3) * mr.y;
  float2 muv = float2(uv.x + sh.y * (mr.x - d) * 0.6 / rc.z, uv.y + 2 * (mr.x - d) / rc.w);
  c = lerp(c, tex2D(scn, clamp(muv, k0.xy, 1 - k0.xy)).rgb, mw);
  // Блики: свет сквозь волну собирается под выпуклостью (линза) и рассеивается под впадиной — чем глубже, тем
  // сильнее; поверхность берётся над точкой, сдвинутой по наклону (луч преломился)
  // (кривизна — средняя по двум точкам: под крутой воронкой свет не режется полосами)
  float xs = w.x - d * sh.y * 0.25;
  float kz = (surface(xs - 12, t).z + surface(xs + 12, t).z) * 0.5;
  // Глубже фокуса свет снова рассеивается: глубина для линзы — не больше ~120 px
  float dl = d / (1 + d / 120);
  float lens = clamp(1 + dl * kz * 4, 0.75, 1.5);
  float fade = saturate(1 - d / tn.w);
  float cs = mr.w > 0.5 ? causticTile(w + off * 4, t) : caustic(w + off * 4, t);
  c += cs * pr.w * lens * under * fade * float3(0.8, 0.95, 1);
  c *= 1 + (lens - 1) * 0.12 * under * fade;
  // Каверна — воздух в воде: стенки полости отражают свет целиком (серебро), за ней толща видна блекло, край ярче
  float sd = 1e5;
  for (int i = 0; i < 21; i++)
    sd = min(sd, length(w - cv[i].xy) - cv[i].z);
  // (над кромкой полости нет — там воронка самой поверхности)
  float wet = saturate(d / 4);
  float inAir = saturate(-sd / 2.5) * wet;
  float rim = saturate(1 - abs(sd + 1) / 2.5) * wet;
  c = lerp(c, c * 0.35 + float3(0.62, 0.78, 0.85), inAir * 0.85);
  c += rim * float3(0.45, 0.5, 0.52);
  // Мелкие пузырьки — молочная белизна, ил — муть тоном st (st.a — сила)
  c = lerp(c, float3(0.82, 0.93, 0.97), saturate(ga.r * 0.75) * under);
  c = lerp(c, st.rgb, saturate(ga.g * st.a) * under);
  c *= lerp(float3(1, 1, 1), tn.rgb, under);
  // Дымка толщи: глубже свет гаснет и рассеивается — картинка уходит в цвет воды (плавно, без ступеньки у кромки)
  float hd = saturate(d / dz.x);
  c = lerp(c, hz.rgb, hd * (2 - hd) * hz.a * under);
  return float4(c, 1) * col.a;
}

shaders.glsl:
#version 300 es
precision highp float;
precision highp int;
uniform vec4 k[40];
#define k0 k[0]
#define rc k[1]
#define sw k[2]
#define pr k[3]
#define tn k[4]
#define sf k[5]
#define gm k[6]
#define mr k[7]
#define ct k[29]
#define hz k[30]
#define dz k[31]
#define sw1 k[32]
#define sw2 k[33]
#define sw3 k[34]
#define fr k[35]
#define cz k[36]
#define ctr k[37]
#define cts k[38]
#define st k[39]
#define saturate(x) clamp(x,0.0,1.0)
in vec2 vUV;in vec2 vUV2;in vec4 vColor;out vec4 outColor;uniform vec4 flip;
uniform sampler2D s0;
vec4 sample_scn(vec2 p){return texture(s0,vec2(p.x,mix(p.y,1.0-p.y,flip[0])));}
uniform sampler2D s1;
vec4 sample_grd(vec2 p){return texture(s1,vec2(p.x,mix(p.y,1.0-p.y,flip[1])));}
uniform sampler2D s2;
vec4 sample_srf(vec2 p){return texture(s2,vec2(p.x,mix(p.y,1.0-p.y,flip[2])));}
uniform sampler2D s3;
vec4 sample_cst(vec2 p){return texture(s3,vec2(p.x,mix(p.y,1.0-p.y,flip[3])));}



























vec3 swell(float x, float t, vec4 q)
{
  float a = x * q.x + t * q.y + q.w;
  return vec3(sin(a), q.x * cos(a), -q.x * q.x * sin(a)) * q.z;
}



vec3 surface(float x, float t)
{
  vec3 z = swell(x, t, sw1) + swell(x, t, sw2) + swell(x, t, sw3);
  float u = ((x - sf.x) * sf.y + 0.5) * sf.z;
  vec3 f = sample_srf( vec2(u, 0.5)).rgb * 255.0 - 128.0;
  return vec3(z.x + f.r * 0.5, z.y + f.g / 127.0, z.z + f.b / 2540.0);
}

float caustic(vec2 p, float t)
{
  vec2 q = p * 0.011;
  float v = sin(q.x * 3.1 + t * 0.9 + sin(q.y * 2.3 + t * 0.7) * 1.6) +
    sin(q.y * 3.7 - t * 0.8 + sin(q.x * 2.9 - t * 0.6) * 1.6) + sin((q.x + q.y) * 2.6 + t * 1.1);
  float a = saturate(1.0 - abs(v) * 0.9);
  return a * a * a * a;
}



float causticTile(vec2 p, float t)
{
  vec2 q1 = p / dz.w + vec2(t * 0.021, t * 0.013);
  vec2 q2 = p / (dz.w * 1.37) + vec2(0.37 - t * 0.017, 0.11 + t * 0.019);
  float a = sample_cst( ct.xy + fract(q1) * ct.zw).g;
  float b = sample_cst( ct.xy + fract(q2) * ct.zw).g;
  return saturate((min(a, b) - mr.z) / (1.0 - mr.z));
}
vec4 shade(vec2 uv , vec4 col )
{
  vec2 w = rc.xy + uv * rc.zw;
  float t = sw.w;
  vec3 sh = surface(w.x, t);
  float h = sh.x;
  float dy = w.y - sw.x;

  float bump = saturate(1.0 - abs(dy) / (dy < 0.0 ? pr.x : pr.y));
  bump = bump * bump * (3.0 - 2.0 * bump);
  float d = dy - h;
  float under = saturate(d / 30.0);


  vec2 gq = (w - gm.xy) * gm.zw;
  vec3 gs = sample_grd( gq).rgb;
  vec2 ga = gs.rg;
  float axl = sample_grd( gq - vec2(gm.z * 10.0, 0.0)).r;
  float ayu = sample_grd( gq - vec2(0.0, gm.w * 10.0)).r;


  float nz = exp(-max(d, 0.0) / dz.y) * dz.z;
  float ka = mix(1.0, 0.35 + 1.3 * nz, dz.z);
  vec2 off;

  vec2 fw = w * fr.x;
  float ft = t * fr.y;
  off.x = (sin(w.y * 0.05 + t * 1.3 + sin(w.x * 0.012 + t * 0.5) * 2.0) * ka +
    sin(fw.y * 0.13 + ft * 3.1 + sin(fw.x * 0.037 - ft * 1.4) * 1.5) * 0.7 * nz) * pr.z * under;
  off.y = -h * bump + (cos(w.x * 0.04 - t * 1.1) * 0.5 * ka + cos(fw.x * 0.11 + ft * 2.6) * 0.4 * nz) * pr.z * under;
  off += vec2(ga.r - axl, ga.r - ayu) * 5.0 * under;


  vec2 cg = vec2(sample_grd( gq + vec2(cz.z, 0.0)).b - sample_grd( gq - vec2(cz.z, 0.0)).b,
    sample_grd( gq + vec2(0.0, cz.w)).b - sample_grd( gq - vec2(0.0, cz.w)).b) * (255.0 / 254.0);
  off += cg * cz.x * under;



  if (cts.z > 0.0)
  {
    float ch = (gs.b * 255.0 - 128.0) / 127.0;
    vec2 q = w / cts.xy + vec2(t * 0.013, -t * 0.009) + ch * vec2(0.12, 0.07);
    vec2 e = vec2(cts.w, cts.w * cts.x / cts.y);
    vec2 hs = vec2(sample_cst( ctr.xy + fract(q + vec2(e.x, 0.0)) * ctr.zw).g -
      sample_cst( ctr.xy + fract(q - vec2(e.x, 0.0)) * ctr.zw).g,
      sample_cst( ctr.xy + fract(q + vec2(0.0, e.y)) * ctr.zw).g - sample_cst( ctr.xy + fract(q - vec2(0.0, e.y)) * ctr.zw).g);
    off += hs * 16.0 * cts.z * abs(ch) * under;
  }
  vec2 suv = clamp(uv + off / rc.zw, k0.xy, 1.0 - k0.xy);
  vec3 c = sample_scn( suv).rgb;


  float m = saturate(d / mr.x);
  float mw = (1.0 - m) * (1.0 - m) * saturate(d / 3.0) * mr.y;
  vec2 muv = vec2(uv.x + sh.y * (mr.x - d) * 0.6 / rc.z, uv.y + 2.0 * (mr.x - d) / rc.w);
  c = mix(c, sample_scn( clamp(muv, k0.xy, 1.0 - k0.xy)).rgb, mw);



  float xs = w.x - d * sh.y * 0.25;
  float kz = (surface(xs - 12.0, t).z + surface(xs + 12.0, t).z) * 0.5;

  float dl = d / (1.0 + d / 120.0);
  float lens = clamp(1.0 + dl * kz * 4.0, 0.75, 1.5);
  float fade = saturate(1.0 - d / tn.w);
  float cs = mr.w > 0.5 ? causticTile(w + off * 4.0, t) : caustic(w + off * 4.0, t);
  c += cs * pr.w * lens * under * fade * vec3(0.8, 0.95, 1.0);
  c *= 1.0 + (lens - 1.0) * 0.12 * under * fade;

  float sd = 1e5;
  for (int i = 0; i < 21; i++)
    sd = min(sd, length(w - k[8+(i)].xy) - k[8+(i)].z);

  float wet = saturate(d / 4.0);
  float inAir = saturate(-sd / 2.5) * wet;
  float rim = saturate(1.0 - abs(sd + 1.0) / 2.5) * wet;
  c = mix(c, c * 0.35 + vec3(0.62, 0.78, 0.85), inAir * 0.85);
  c += rim * vec3(0.45, 0.5, 0.52);

  c = mix(c, vec3(0.82, 0.93, 0.97), saturate(ga.r * 0.75) * under);
  c = mix(c, st.rgb, saturate(ga.g * st.a) * under);
  c *= mix(vec3(1.0, 1.0, 1.0), tn.rgb, under);

  float hd = saturate(d / dz.x);
