// Шейдер MURK_HLSL (water.pas, TWaterMurk): муть по течению, рисуется умножением. s0 — плитка мути (кадр атласа,
// TEXCOORD0; белое — чисто), s1 — отклонение мути от плитки на клетках сетки течения (TEXCOORD1 — доли сетки;
// r = 128 + отклонение·127). c1 = (тон мути, сила), c2 = (где под кромкой муть начинается — доля сетки по высоте,
// 1/длина растушёвки в долях). Строки-комментарии // в exe не попадают: build.ps1 собирает файл в константу
// (build\gen\murk_hlsl.inc).
sampler2D tile : register(s0);
sampler2D dev : register(s1);
float4 k0 : register(c0);
float4 mc : register(c1);
float4 mf : register(c2);
float4 main(float2 uv : TEXCOORD0, float2 uv2 : TEXCOORD1, float4 col : COLOR0) : COLOR0
{
  float3 t = tex2D(tile, uv).rgb;
  float d = (tex2D(dev, uv2).r * 255 - 128) / 127;
  // Плитка: мути столько, насколько она темнее белого; отклонение добавляет или убирает муть её тоном
  float3 m = saturate((1 - t) + d * (1 - mc.rgb));
  // Сверху — растушёвка: у кромки мути нет, к глубине — вся
  float f = saturate((uv2.y - mf.x) * mf.y);
  return float4(1 - m * mc.w * f * col.a, 1);
}

