// Шейдер FIELD_VS (particles.pas). Строки-комментарии // в exe не попадают: build.ps1 собирает
// файл в константу (build\gen\particles_vs_hlsl.inc).
float4 p0 : register(c0);
float4 p1 : register(c1);
float4 area : register(c4);
float4 vel : register(c5);
float4 mot : register(c6);
float4 sz : register(c7);
float4 reg : register(c8);
float4 ext : register(c9);
float4 tint : register(c10);
struct VOut { float4 pos : POSITION; float2 uv : TEXCOORD0; float4 col : COLOR0; };
float hash(float n) { return frac(sin(n) * 43758.5453); }
VOut main(float4 a : TEXCOORD0, float4 b : TEXCOORD1, float4 c : TEXCOORD2)
{
  VOut o;
  float t = ext.w;
  float hasLife = step(0.0001, vel.w);
  float life = max(vel.w, 0.0001);
  // Жизнь: номер цикла и доля прожитого; в каждом цикле — новое случайное место
  float ph = t / life + b.x;
  float cyc = floor(ph);
  float k = lerp(0.5, ph - cyc, hasLife);
  float rx = lerp(a.z, hash(cyc * 12.9898 + a.z * 78.233), hasLife);
  float ry = lerp(a.w, hash(cyc * 39.346 + a.w * 11.135), hasLife);
  float tt = lerp(t, k * life, hasLife);
  float fade = lerp(1, sin(k * 3.14159), hasLife);
  float2 v = vel.xy * (1 + (b.y - 0.5) * 2 * vel.z);
  float2 w;
  w.x = rx * area.x + v.x * tt + sin(t * mot.y * 6.2832 + b.z * 6.2832) * mot.x - area.z;
  w.y = ry * area.y + v.y * tt - area.w;
  // Перенос в окно вокруг камеры; на линии — y сама линия
  w.x = frac(w.x / area.x) * area.x - ext.x;
  float onLine = step(0, ext.y);
  w.y = lerp(frac(w.y / area.y) * area.y - ext.x, ext.y - area.w, onLine);
  float size = lerp(sz.x, sz.y, b.w) * lerp(1, ext.z, k);
  float2 q = (a.xy - 0.5) * c.zw * size;
  // Вытягивание вдоль скорости (дождь) или вращение (листья, снег)
  float2 d = normalize(v + float2(0.0001, 0.0001));
  float2 qs = float2(q.x * d.y + q.y * d.x * mot.w, -q.x * d.x + q.y * d.y * mot.w);
  float ang = mot.z * (b.z - 0.5) * 2 * t + b.x * 6.2832;
  float cs = cos(ang);
  float sn = sin(ang);
  float2 qr = float2(q.x * cs - q.y * sn, q.x * sn + q.y * cs);
  float2 pos = w + lerp(qr, qs, step(0.0001, mot.w));
  // Мягкие края области (в мировых x)
  float wx = w.x + area.z;
  float inReg = saturate((wx - reg.x) / reg.z) * saturate((reg.y - wx) / reg.z);
  float rf = lerp(1, inReg, step(reg.x + 0.5, reg.y));
  float al = tint.a * reg.w * fade * rf;
  float2 s = p0.zw + pos * p1.x - 0.5;
  o.pos = float4(s.x * p0.x - 1, s.y * p0.y + 1, 0, 1);
  o.uv = c.xy;
  o.col = float4(tint.rgb * al, al);
  return o;
}

