// Шейдер PLACE_HLSL (shading.pas). Строки-комментарии // в exe не попадают: build.ps1 собирает
// файл в константу (build\gen\place_hlsl.inc).
sampler2D spr : register(s0);
sampler2D place : register(s1);
float4 texel : register(c0);
float4 light : register(c1);
float4 look : register(c2);
static const float3 W = float3(0.2126, 0.7152, 0.0722);
float4 main(float2 uv : TEXCOORD0, float2 puv : TEXCOORD1, float4 col : COLOR0) : COLOR0
{
  // Мягкость: центр и четыре соседа по диагонали
  float2 d = texel.xy * look.y;
  float4 s = tex2D(spr, uv) * 0.5 + (tex2D(spr, uv + d) + tex2D(spr, uv - d) +
    tex2D(spr, uv + float2(d.x, -d.y)) + tex2D(spr, uv + float2(-d.x, d.y))) * 0.125;
  // Свет места — та же формула, что LightTint в gamelogic.pas
  float3 amb = tex2D(place, puv).rgb;
  float lum = dot(amb, W);
  float lit = saturate(lum / light.x);
  float shade = lerp(light.y, 1, lit);
  float tone = light.z * (1 - lit);
  float3 hue = clamp((amb + 0.03) / (lum + 0.03), 0, 2);
  float3 c = s.rgb * saturate(shade * (1 + tone * (hue - 1)));
  // Подъём тёмного: в тени чёрный контур — цвета места (рассеянный свет); на солнце контур как нарисован
  float dark = 1 - saturate(dot(s.rgb / max(s.a, 0.004), W) * 5);
  c += amb * light.w * (1 - lit) * dark * s.a;
  return float4(c, s.a) * col;
}

